-- Блоки «Выбирай X, если…» и FAQ сравнений, пересобраны из проверенных карточек, 2026-10-11.
-- Было / стало: scripts/audit/comparisons_2026-10-11_review.json. Идемпотентно.

-- nano-banana-vs-leonardo-ai
UPDATE comparisons SET choose_a = $c$["✅ You want to generate and edit images for free directly inside the Gemini app using Nano Banana 2", "✅ You need multi-turn conversational editing with character consistency across a series of images, especially with Nano Banana 2.1", "✅ You need accurate text rendering or search-grounded generation that draws on Gemini's real-world knowledge", "✅ You want studio-quality precision up to 4K output and are willing to use Nano Banana Pro via the Gemini API or AI Studio"]$c$, choose_b = $c$["✅ You create game assets, concept art, or marketing visuals and want access to multiple proprietary and licensed models in one platform", "✅ You want to train a personal AI model on your own images to keep a consistent style or character across a project", "✅ You need image-to-video generation alongside still images, using models like Motion 2.0 or Hailuo 2.3", "✅ You want a pay-as-you-go API with non-expiring credits and the ability to run up to 10 concurrent generations"]$c$, faq = $c$[{"q": "What is Nano Banana?", "a": "Nano Banana is Google's family of Gemini image generation and editing models, including Nano Banana 2, 2 Lite, 2.1 and Pro, accessible through the Gemini app, Google AI Studio and the Gemini API. It supports multi-turn conversational editing, character consistency, and output up to 4K."}, {"q": "What is Leonardo AI best for?", "a": "Leonardo AI is built for game developers, concept artists, and creative teams who need high-volume image and video generation across multiple models, including sketch-to-image tools, a canvas editor, and a visual API workflow that exports production-ready code."}, {"q": "Which is better for character consistency across a series of images?", "a": "Nano Banana 2.1 offers multi-turn character consistency directly through conversational editing in the Gemini app or API. Leonardo AI instead lets you train a personal AI model on your own images to maintain a consistent style or character, which suits project-based work like game asset series."}, {"q": "Is Nano Banana free to use?", "a": "Nano Banana 2 is free to use in the Gemini app with no numeric usage limits published, but Nano Banana 2.1 and the Pro redo option require a paid Google AI plan. The Gemini API has no free tier and bills per output image for all models in the family."}, {"q": "Does Leonardo AI have a free plan?", "a": "Yes, Leonardo AI's FREE plan gives 150 Fast Tokens per day with public-only creations and basic quality settings, which is enough to try the platform but limited for professional volume use."}]$c$::jsonb
 WHERE slug = 'nano-banana-vs-leonardo-ai' AND lang = 'en';
UPDATE comparisons SET choose_a = $c$["✅ Quieres generar y editar imágenes gratis directamente dentro de la app de Gemini usando Nano Banana 2", "✅ Necesitas edición conversacional multi-turno con consistencia de personajes a través de una serie de imágenes, especialmente con Nano Banana 2.1", "✅ Necesitas renderizado de texto preciso o generación basada en búsquedas que aproveche el conocimiento del mundo real de Gemini", "✅ Quieres precisión de calidad de estudio hasta salida en 4K y estás dispuesto a usar Nano Banana Pro a través de la API de Gemini o AI Studio"]$c$, choose_b = $c$["✅ Creas assets de videojuegos, arte conceptual o visuales de marketing y quieres acceso a múltiples modelos propietarios y con licencia en una sola plataforma", "✅ Quieres entrenar un modelo de IA personal con tus propias imágenes para mantener un estilo o personaje consistente a lo largo de un proyecto", "✅ Necesitas generación de imagen a video junto con imágenes fijas, usando modelos como Motion 2.0 o Hailuo 2.3", "✅ Quieres una API de pago por uso con créditos que no caducan y la capacidad de ejecutar hasta 10 generaciones simultáneas"]$c$, faq = $c$[{"q": "¿Qué es Nano Banana?", "a": "Nano Banana es la familia de modelos de generación y edición de imágenes de Gemini de Google, que incluye Nano Banana 2, 2 Lite, 2.1 y Pro, accesibles a través de la app de Gemini, Google AI Studio y la API de Gemini. Admite edición conversacional multi-turno, consistencia de personajes y salida hasta 4K."}, {"q": "¿Para qué es mejor Leonardo AI?", "a": "Leonardo AI está diseñado para desarrolladores de videojuegos, artistas conceptuales y equipos creativos que necesitan generación de imágenes y video de alto volumen a través de múltiples modelos, incluyendo herramientas de boceto a imagen, un editor de lienzo y un flujo de trabajo de API visual que exporta código listo para producción."}, {"q": "¿Cuál es mejor para la consistencia de personajes a través de una serie de imágenes?", "a": "Nano Banana 2.1 ofrece consistencia de personajes multi-turno directamente a través de la edición conversacional en la app de Gemini o la API. Leonardo AI, en cambio, te permite entrenar un modelo de IA personal con tus propias imágenes para mantener un estilo o personaje consistente, lo cual es adecuado para trabajos basados en proyectos como series de assets de videojuegos."}, {"q": "¿Es Nano Banana gratis de usar?", "a": "Nano Banana 2 es gratis de usar en la app de Gemini sin límites de uso numéricos publicados, pero Nano Banana 2.1 y la opción de reedición Pro requieren un plan pago de Google AI. La API de Gemini no tiene nivel gratuito y cobra por imagen de salida para todos los modelos de la familia."}, {"q": "¿Leonardo AI tiene un plan gratuito?", "a": "Sí, el plan FREE de Leonardo AI ofrece 150 Fast Tokens por día con creaciones solo públicas y configuraciones de calidad básicas, lo cual es suficiente para probar la plataforma pero limitado para uso profesional de volumen."}]$c$::jsonb
 WHERE slug = 'nano-banana-vs-leonardo-ai' AND lang = 'es';
UPDATE comparisons SET choose_a = $c$["✅ Du möchtest kostenlos direkt in der Gemini-App mit Nano Banana 2 Bilder erstellen und bearbeiten", "✅ Du brauchst mehrstufige, dialogbasierte Bearbeitung mit Charakterkonsistenz über eine Serie von Bildern hinweg, besonders mit Nano Banana 2.1", "✅ Du benötigst präzise Textdarstellung oder suchbasierte Generierung, die auf Geminis Weltwissen zurückgreift", "✅ Du möchtest Studioqualität mit Präzision bis zu 4K-Auflösung und bist bereit, Nano Banana Pro über die Gemini API oder AI Studio zu nutzen"]$c$, choose_b = $c$["✅ Du erstellst Game-Assets, Concept Art oder Marketing-Visuals und möchtest in einer Plattform Zugriff auf mehrere proprietäre und lizenzierte Modelle haben", "✅ Du möchtest ein persönliches KI-Modell mit deinen eigenen Bildern trainieren, um einen konsistenten Stil oder Charakter über ein Projekt hinweg beizubehalten", "✅ Du brauchst Bild-zu-Video-Generierung neben Standbildern, mit Modellen wie Motion 2.0 oder Hailuo 2.3", "✅ Du möchtest eine Pay-as-you-go-API mit nicht verfallenden Credits und der Möglichkeit, bis zu 10 Generierungen gleichzeitig auszuführen"]$c$, faq = $c$[{"q": "Was ist Nano Banana?", "a": "Nano Banana ist Googles Familie von Gemini-Bildgenerierungs- und Bearbeitungsmodellen, darunter Nano Banana 2, 2 Lite, 2.1 und Pro, zugänglich über die Gemini-App, Google AI Studio und die Gemini API. Es unterstützt mehrstufige, dialogbasierte Bearbeitung, Charakterkonsistenz und Ausgaben bis zu 4K."}, {"q": "Wofür eignet sich Leonardo AI am besten?", "a": "Leonardo AI wurde für Game-Entwickler, Concept Artists und Kreativteams entwickelt, die hochvolumige Bild- und Videogenerierung über mehrere Modelle hinweg benötigen, einschließlich Sketch-to-Image-Tools, einem Canvas-Editor und einem visuellen API-Workflow, der produktionsreifen Code exportiert."}, {"q": "Was eignet sich besser für Charakterkonsistenz über eine Bildserie hinweg?", "a": "Nano Banana 2.1 bietet mehrstufige Charakterkonsistenz direkt über die dialogbasierte Bearbeitung in der Gemini-App oder API. Leonardo AI hingegen lässt dich ein persönliches KI-Modell mit deinen eigenen Bildern trainieren, um einen konsistenten Stil oder Charakter beizubehalten, was sich für projektbasierte Arbeit wie Game-Asset-Serien eignet."}, {"q": "Ist Nano Banana kostenlos nutzbar?", "a": "Nano Banana 2 ist in der Gemini-App kostenlos nutzbar, ohne veröffentlichte numerische Nutzungslimits, aber Nano Banana 2.1 und die Pro-Redo-Option erfordern einen kostenpflichtigen Google AI-Plan. Die Gemini API hat keine kostenlose Stufe und berechnet pro Ausgabebild für alle Modelle der Familie."}, {"q": "Hat Leonardo AI einen kostenlosen Plan?", "a": "Ja, Leonardo AIs FREE-Plan bietet 150 Fast Tokens pro Tag mit ausschließlich öffentlichen Kreationen und grundlegenden Qualitätseinstellungen, was ausreicht, um die Plattform auszuprobieren, aber für professionelle Nutzung im großen Umfang begrenzt ist."}]$c$::jsonb
 WHERE slug = 'nano-banana-vs-leonardo-ai' AND lang = 'de';
UPDATE comparisons SET choose_a = $c$["✅ Вы хотите бесплатно генерировать и редактировать изображения прямо в приложении Gemini с помощью Nano Banana 2", "✅ Вам нужно многошаговое диалоговое редактирование с сохранением консистентности персонажей в серии изображений, особенно с Nano Banana 2.1", "✅ Вам нужен точный рендеринг текста или генерация с опорой на поиск, использующая реальные знания Gemini", "✅ Вы хотите студийную точность с выводом до 4K и готовы использовать Nano Banana Pro через Gemini API или AI Studio"]$c$, choose_b = $c$["✅ Вы создаёте игровые ассеты, концепт-арт или маркетинговые визуалы и хотите доступ к нескольким проприетарным и лицензированным моделям на одной платформе", "✅ Вы хотите обучить персональную AI-модель на собственных изображениях, чтобы сохранить единый стиль или персонажа в рамках проекта", "✅ Вам нужна генерация видео из изображений наряду со статичными изображениями, используя такие модели, как Motion 2.0 или Hailuo 2.3", "✅ Вы хотите API с оплатой по факту использования, несгораемыми кредитами и возможностью запускать до 10 одновременных генераций"]$c$, faq = $c$[{"q": "Что такое Nano Banana?", "a": "Nano Banana — это семейство моделей Google Gemini для генерации и редактирования изображений, включающее Nano Banana 2, 2 Lite, 2.1 и Pro, доступное через приложение Gemini, Google AI Studio и Gemini API. Оно поддерживает многошаговое диалоговое редактирование, консистентность персонажей и вывод до 4K."}, {"q": "Для чего лучше всего подходит Leonardo AI?", "a": "Leonardo AI создан для разработчиков игр, концепт-художников и творческих команд, которым нужна генерация большого объёма изображений и видео с использованием нескольких моделей, включая инструменты sketch-to-image, редактор canvas и визуальный API-воркфлоу, экспортирующий готовый к продакшену код."}, {"q": "Что лучше подходит для сохранения консистентности персонажа в серии изображений?", "a": "Nano Banana 2.1 предлагает многошаговую консистентность персонажей прямо через диалоговое редактирование в приложении Gemini или API. Leonardo AI вместо этого позволяет обучить персональную AI-модель на собственных изображениях для поддержания единого стиля или персонажа, что подходит для проектной работы, например серий игровых ассетов."}, {"q": "Бесплатен ли Nano Banana?", "a": "Nano Banana 2 бесплатен для использования в приложении Gemini без опубликованных числовых лимитов использования, но Nano Banana 2.1 и опция повторной генерации Pro требуют платного плана Google AI. У Gemini API нет бесплатного уровня, и оплата взимается за каждое выходное изображение для всех моделей семейства."}, {"q": "Есть ли у Leonardo AI бесплатный план?", "a": "Да, план FREE в Leonardo AI даёт 150 Fast Tokens в день с созданием только публичных работ и базовыми настройками качества, чего достаточно, чтобы попробовать платформу, но мало для профессионального использования в больших объёмах."}]$c$::jsonb
 WHERE slug = 'nano-banana-vs-leonardo-ai' AND lang = 'ru';
UPDATE comparisons SET choose_a = $c$["✅ Ви хочете безкоштовно створювати та редагувати зображення прямо в застосунку Gemini за допомогою Nano Banana 2", "✅ Вам потрібне багаторазове редагування в режимі діалогу зі збереженням послідовності персонажів у серії зображень, особливо з Nano Banana 2.1", "✅ Вам потрібен точний рендеринг тексту або генерація на основі пошуку, що спирається на знання Gemini про реальний світ", "✅ Ви хочете студійну точність аж до виводу 4K і готові використовувати Nano Banana Pro через Gemini API або AI Studio"]$c$, choose_b = $c$["✅ Ви створюєте ігрові ассети, концепт-арт або маркетингові візуали та хочете мати доступ до кількох пропрієтарних і ліцензованих моделей на одній платформі", "✅ Ви хочете натренувати персональну AI-модель на власних зображеннях, щоб зберегти послідовний стиль або персонажа протягом проєкту", "✅ Вам потрібна генерація відео із зображення поряд зі статичними зображеннями, з використанням таких моделей, як Motion 2.0 або Hailuo 2.3", "✅ Ви хочете API з оплатою за використанням, кредитами без терміну дії та можливістю запускати до 10 одночасних генерацій"]$c$, faq = $c$[{"q": "Що таке Nano Banana?", "a": "Nano Banana — це сімейство моделей Google Gemini для генерації та редагування зображень, що включає Nano Banana 2, 2 Lite, 2.1 і Pro, доступних через застосунок Gemini, Google AI Studio та Gemini API. Воно підтримує багаторазове редагування в режимі діалогу, послідовність персонажів і вивід до 4K."}, {"q": "Для чого найкраще підходить Leonardo AI?", "a": "Leonardo AI створений для розробників ігор, концепт-художників і творчих команд, яким потрібна масштабна генерація зображень і відео на основі кількох моделей, включно з інструментами sketch-to-image, редактором canvas і візуальним API-воркфлоу, що експортує готовий до використання код."}, {"q": "Що краще для збереження послідовності персонажів у серії зображень?", "a": "Nano Banana 2.1 пропонує збереження послідовності персонажів у багаторазовому режимі прямо через діалогове редагування в застосунку Gemini або API. Leonardo AI натомість дозволяє натренувати персональну AI-модель на власних зображеннях для підтримки послідовного стилю або персонажа, що підходить для проєктної роботи, як-от серії ігрових ассетів."}, {"q": "Чи можна користуватися Nano Banana безкоштовно?", "a": "Nano Banana 2 можна безкоштовно використовувати в застосунку Gemini без опублікованих числових лімітів використання, але Nano Banana 2.1 і опція Pro redo вимагають платного плану Google AI. Gemini API не має безкоштовного рівня і виставляє рахунок за кожне вихідне зображення для всіх моделей цього сімейства."}, {"q": "Чи є в Leonardo AI безкоштовний план?", "a": "Так, безкоштовний план FREE у Leonardo AI надає 150 Fast Tokens на день із лише публічними створеннями та базовими налаштуваннями якості, чого достатньо, щоб спробувати платформу, але замало для професійного обсягу використання."}]$c$::jsonb
 WHERE slug = 'nano-banana-vs-leonardo-ai' AND lang = 'ua';
UPDATE comparisons SET choose_a = $c$["✅ אתם רוצים ליצור ולערוך תמונות בחינם ישירות בתוך אפליקציית Gemini באמצעות Nano Banana 2", "✅ אתם זקוקים לעריכה שיחתית מרובת-סבבים עם עקביות דמויות לאורך סדרת תמונות, במיוחד עם Nano Banana 2.1", "✅ אתם זקוקים לרינדור טקסט מדויק או ליצירה מבוססת-חיפוש הנשענת על הידע העולמי של Gemini", "✅ אתם רוצים דיוק ברמת סטודיו עד פלט 4K ומוכנים להשתמש ב-Nano Banana Pro דרך Gemini API או AI Studio"]$c$, choose_b = $c$["✅ אתם יוצרים נכסי משחק, קונספט ארט, או ויז'ואלים שיווקיים ורוצים גישה למספר מודלים קנייניים ומורשים בפלטפורמה אחת", "✅ אתם רוצים לאמן מודל AI אישי על התמונות שלכם כדי לשמור על סגנון או דמות עקביים לאורך פרויקט", "✅ אתם זקוקים ליצירת image-to-video לצד תמונות סטילס, באמצעות מודלים כמו Motion 2.0 או Hailuo 2.3", "✅ אתם רוצים API בתשלום לפי שימוש עם קרדיטים שאינם פוקעים ויכולת להריץ עד 10 יצירות במקביל"]$c$, faq = $c$[{"q": "מהו Nano Banana?", "a": "Nano Banana הוא משפחת המודלים של Google ליצירה ועריכה של תמונות ב-Gemini, הכוללת את Nano Banana 2, 2 Lite, 2.1 ו-Pro, הנגישים דרך אפליקציית Gemini, Google AI Studio ו-Gemini API. הוא תומך בעריכה שיחתית מרובת-סבבים, עקביות דמויות, ופלט עד 4K."}, {"q": "למה Leonardo AI הכי מתאים?", "a": "Leonardo AI נבנה עבור מפתחי משחקים, אמני קונספט, וצוותים יצירתיים הזקוקים ליצירת תמונות ווידאו בנפח גבוה במגוון מודלים, כולל כלי sketch-to-image, עורך קנבס, ותהליך עבודה של API חזותי המייצא קוד מוכן לייצור."}, {"q": "מה עדיף לעקביות דמויות לאורך סדרת תמונות?", "a": "Nano Banana 2.1 מציע עקביות דמויות מרובת-סבבים ישירות דרך עריכה שיחתית באפליקציית Gemini או ב-API. לעומת זאת, Leonardo AI מאפשר לכם לאמן מודל AI אישי על התמונות שלכם כדי לשמור על סגנון או דמות עקביים, מה שמתאים לעבודה מבוססת-פרויקט כמו סדרות נכסי משחק."}, {"q": "האם Nano Banana חינמי לשימוש?", "a": "Nano Banana 2 חינמי לשימוש באפליקציית Gemini ללא מגבלות שימוש מספריות מפורסמות, אך Nano Banana 2.1 ואפשרות ה-redo של Pro דורשים תוכנית Google AI בתשלום. ל-Gemini API אין רמה חינמית והוא מחייב לפי תמונת פלט עבור כל המודלים במשפחה."}, {"q": "האם ל-Leonardo AI יש תוכנית חינמית?", "a": "כן, תוכנית ה-FREE של Leonardo AI מעניקה 150 Fast Tokens ליום עם יצירות ציבוריות בלבד והגדרות איכות בסיסיות, מה שמספיק כדי לנסות את הפלטפורמה אך מוגבל לשימוש מקצועי בנפח גבוה."}]$c$::jsonb
 WHERE slug = 'nano-banana-vs-leonardo-ai' AND lang = 'he';
UPDATE comparisons SET choose_a = $c$["✅ Vous voulez générer et modifier des images gratuitement directement dans l'application Gemini avec Nano Banana 2", "✅ Vous avez besoin d'une édition conversationnelle multi-tours avec une cohérence des personnages sur une série d'images, notamment avec Nano Banana 2.1", "✅ Vous avez besoin d'un rendu de texte précis ou d'une génération ancrée dans la recherche, s'appuyant sur les connaissances du monde réel de Gemini", "✅ Vous voulez une précision de qualité studio allant jusqu'à une sortie en 4K et êtes prêt à utiliser Nano Banana Pro via l'API Gemini ou AI Studio"]$c$, choose_b = $c$["✅ Vous créez des assets de jeu, de l'art conceptuel ou des visuels marketing et voulez accéder à plusieurs modèles propriétaires et sous licence sur une seule plateforme", "✅ Vous voulez entraîner un modèle d'IA personnel sur vos propres images pour conserver un style ou un personnage cohérent tout au long d'un projet", "✅ Vous avez besoin d'une génération d'image à vidéo en plus des images fixes, avec des modèles comme Motion 2.0 ou Hailuo 2.3", "✅ Vous voulez une API à l'usage avec des crédits sans expiration et la possibilité d'exécuter jusqu'à 10 générations simultanées"]$c$, faq = $c$[{"q": "Qu'est-ce que Nano Banana ?", "a": "Nano Banana est la famille de modèles de génération et d'édition d'images Gemini de Google, incluant Nano Banana 2, 2 Lite, 2.1 et Pro, accessibles via l'application Gemini, Google AI Studio et l'API Gemini. Elle prend en charge l'édition conversationnelle multi-tours, la cohérence des personnages et une sortie allant jusqu'à 4K."}, {"q": "Pour quoi Leonardo AI est-il le mieux adapté ?", "a": "Leonardo AI est conçu pour les développeurs de jeux, les artistes conceptuels et les équipes créatives qui ont besoin d'une génération d'images et de vidéos à grand volume sur plusieurs modèles, incluant des outils de croquis vers image, un éditeur de canevas et un flux de travail d'API visuelle qui exporte du code prêt pour la production."}, {"q": "Lequel est le meilleur pour la cohérence des personnages sur une série d'images ?", "a": "Nano Banana 2.1 offre une cohérence des personnages multi-tours directement via l'édition conversationnelle dans l'application ou l'API Gemini. Leonardo AI, de son côté, permet d'entraîner un modèle d'IA personnel sur vos propres images pour maintenir un style ou un personnage cohérent, ce qui convient à un travail basé sur des projets comme des séries d'assets de jeu."}, {"q": "Nano Banana est-il gratuit à utiliser ?", "a": "Nano Banana 2 est gratuit à utiliser dans l'application Gemini sans limites d'utilisation numériques publiées, mais Nano Banana 2.1 et l'option de retouche Pro nécessitent un plan Google AI payant. L'API Gemini n'a pas de niveau gratuit et facture par image de sortie pour tous les modèles de la famille."}, {"q": "Leonardo AI a-t-il un plan gratuit ?", "a": "Oui, le plan FREE de Leonardo AI offre 150 Fast Tokens par jour avec des créations publiques uniquement et des paramètres de qualité de base, ce qui est suffisant pour essayer la plateforme mais limité pour un usage professionnel à grand volume."}]$c$::jsonb
 WHERE slug = 'nano-banana-vs-leonardo-ai' AND lang = 'fr';
UPDATE comparisons SET choose_a = $c$["✅ Você quer gerar e editar imagens gratuitamente diretamente no aplicativo Gemini usando o Nano Banana 2", "✅ Você precisa de edição conversacional multi-turno com consistência de personagem em uma série de imagens, especialmente com o Nano Banana 2.1", "✅ Você precisa de renderização precisa de texto ou geração fundamentada em busca que utiliza o conhecimento do mundo real do Gemini", "✅ Você quer precisão de qualidade de estúdio com saída de até 4K e está disposto a usar o Nano Banana Pro via Gemini API ou AI Studio"]$c$, choose_b = $c$["✅ Você cria assets de jogos, arte conceitual ou visuais de marketing e quer acesso a múltiplos modelos proprietários e licenciados em uma única plataforma", "✅ Você quer treinar um modelo de IA pessoal com suas próprias imagens para manter um estilo ou personagem consistente ao longo de um projeto", "✅ Você precisa de geração de imagem para vídeo além de imagens estáticas, usando modelos como Motion 2.0 ou Hailuo 2.3", "✅ Você quer uma API pay-as-you-go com créditos que não expiram e a capacidade de executar até 10 gerações simultâneas"]$c$, faq = $c$[{"q": "O que é o Nano Banana?", "a": "Nano Banana é a família de modelos de geração e edição de imagens Gemini do Google, incluindo Nano Banana 2, 2 Lite, 2.1 e Pro, acessível através do aplicativo Gemini, Google AI Studio e Gemini API. Ele suporta edição conversacional multi-turno, consistência de personagem e saída de até 4K."}, {"q": "Para que o Leonardo AI é melhor?", "a": "O Leonardo AI foi criado para desenvolvedores de jogos, artistas conceituais e equipes criativas que precisam de geração de imagens e vídeos em alto volume usando múltiplos modelos, incluindo ferramentas de sketch-to-image, um editor de canvas e um fluxo de trabalho de API visual que exporta código pronto para produção."}, {"q": "Qual é melhor para consistência de personagem em uma série de imagens?", "a": "O Nano Banana 2.1 oferece consistência de personagem multi-turno diretamente através da edição conversacional no aplicativo Gemini ou na API. Já o Leonardo AI permite treinar um modelo de IA pessoal com suas próprias imagens para manter um estilo ou personagem consistente, o que é adequado para trabalhos baseados em projetos, como séries de assets de jogos."}, {"q": "O Nano Banana é gratuito para usar?", "a": "O Nano Banana 2 é gratuito para usar no aplicativo Gemini, sem limites numéricos de uso publicados, mas o Nano Banana 2.1 e a opção de refazer do Pro exigem um plano pago do Google AI. A Gemini API não tem camada gratuita e cobra por imagem de saída para todos os modelos da família."}, {"q": "O Leonardo AI tem um plano gratuito?", "a": "Sim, o plano FREE do Leonardo AI oferece 150 Fast Tokens por dia com criações apenas públicas e configurações de qualidade básicas, o que é suficiente para experimentar a plataforma, mas limitado para uso profissional de alto volume."}]$c$::jsonb
 WHERE slug = 'nano-banana-vs-leonardo-ai' AND lang = 'pt';
